// src/components/User/CheckoutPage.js
import React, { useState, useRef, useEffect } from 'react'; 
import { useNavigate } from 'react-router-dom';
import HeaderSearch from './HeaderSearch'; 
import './CheckoutPage.css';

// --- useSwipe hook (ADDED isSwiping state logic) ---
function useSwipe({ onSwipe, sensitivity = 20 }) { 
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);
  const [isSwiping, setIsSwiping] = useState(false); // New state flag

  const handleTouchStart = (e) => {
      setTouchStart(e.targetTouches[0].clientX);
      setIsSwiping(false); // Reset on touch start
  }
  
  const handleTouchMove = (e) => {
      e.preventDefault(); 
      setTouchEnd(e.targetTouches[0].clientX);
      // If we move enough, it's definitely a swipe, not a click
      if (Math.abs(touchStart - e.targetTouches[0].clientX) > 5) {
          setIsSwiping(true);
      }
  }

  const handleTouchEnd = () => {
    if (!touchStart || !touchEnd) {
        setIsSwiping(false);
        return;
    }
    const distance = touchStart - touchEnd;
    const isRightSwipe = distance < -sensitivity; 
    
    if (isRightSwipe) {
      onSwipe();
    }
    setTouchStart(null);
    setTouchEnd(null);
    // isSwiping stays true if a swipe was detected, preventing click event.
  };

  return { handleTouchStart, handleTouchMove, handleTouchEnd, isSwiping }; // Export isSwiping
}

// --- CheckoutPage Component ---
export default function CheckoutPage({ cart = [], updateCart, placeOrder, tables = [], userDetails }) {
  const navigate = useNavigate();
  const swipeRef = useRef(null); 
  const [orderType, setOrderType] = useState('Take Away'); 
  const [instructions, setInstructions] = useState('');
  const [showInstructionsModal, setShowInstructionsModal] = useState(false);
  
  const name = userDetails?.name || '';
  const phone = userDetails?.contact || ''; 
  const address = userDetails?.address || '';
  const members = userDetails?.persons || '2';
  
  const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const deliveryCharge = orderType === 'Takeaway' ? 50 : 0;
  const taxes = subtotal * 0.05;
  const grandTotal = subtotal + deliveryCharge + taxes;

  const handlePlaceOrder = () => {
    // Validation
    if (!name || !phone) {
      alert('Please fill in your Name and Contact number from the home screen.');
      return;
    }
    if (orderType === 'Takeaway' && !address) {
      alert('Please fill in your delivery address from the home screen.');
      return;
    }
    
    const selectedTable = tables.find(t => t.status === 'Available');

    placeOrder({
      type: orderType,
      name,
      phone,
      address: orderType === 'Takeaway' ? address : null,
      members: orderType === 'Dine In' ? members : null,
      tableNum: orderType === 'Dine In' ? (selectedTable?.number || 'N/A') : null, 
      instructions,
    });
    navigate('/thankyou');
  };

  const { handleTouchStart, handleTouchMove, handleTouchEnd, isSwiping } = useSwipe({ onSwipe: handlePlaceOrder });

  // --- ATTACH LISTENERS DIRECTLY TO DOM NODE ---
  useEffect(() => {
    const element = swipeRef.current;
    if (!element) return;

    element.addEventListener('touchstart', handleTouchStart, { passive: false });
    element.addEventListener('touchmove', handleTouchMove, { passive: false });
    element.addEventListener('touchend', handleTouchEnd, { passive: true });
    
    return () => {
      element.removeEventListener('touchstart', handleTouchStart);
      element.removeEventListener('touchmove', handleTouchMove);
      element.removeEventListener('touchend', handleTouchEnd);
    };
  }, [handleTouchStart, handleTouchMove, handleTouchEnd]); 

  // --- NEW CLICK HANDLER ---
  const handleClick = (e) => {
    // If a swipe gesture was initiated, ignore the click event.
    if (isSwiping) {
        e.preventDefault();
        return;
    }
    handlePlaceOrder();
  };
  // -------------------------


  return (
    <div className="mobile-container checkout-page">
      
      <HeaderSearch isCheckout={true} />

      <header className="checkout-header">
        <button className="back-btn" onClick={() => navigate(-1)}>←</button>
        <h2>Your Order</h2>
      </header>
      
      <div className="order-type-toggle">
        <button 
          className={orderType === 'Dine In' ? 'active' : ''}
          onClick={() => setOrderType('Dine In')}
        >
          Dine In
        </button>
        <button 
          className={orderType === 'Takeaway' ? 'active' : ''}
          onClick={() => setOrderType('Takeaway')}
        >
          Take Away
        </button>
      </div>

      <div className="cart-summary">
        {cart.map(item => (
          <div key={item.id} className="cart-item-checkout">
            <img src={item.image} alt={item.name} className="cart-item-image" />
            <div className="cart-item-info">
              <h3>{item.name}</h3>
              <p>₹{item.price}</p>
            </div>
            {/* Quantity controls */}
            <div className="quantity-control">
              <button onClick={() => updateCart(item.id, item.quantity - 1)}>−</button>
              <span>{item.quantity}</span>
              <button onClick={() => updateCart(item.id, item.quantity + 1)}>+</button>
            </div>
            {/* Red X button for Marinara ONLY - this is simplified */}
            {item.name.includes("Marinara") && (
                <button className="remove-item-btn" onClick={() => updateCart(item.id, 0)}>×</button>
            )}
          </div>
        ))}
      </div>

      <button className="instructions-btn" onClick={() => setShowInstructionsModal(true)}>
        Add cooking instructions (optional) 
      </button>

      {/* Bill Details */}
      <div className="bill-details">
        <div className="bill-row">
          <span>Item Total</span>
          <span>₹{subtotal.toFixed(2)}</span>
        </div>
        {orderType === 'Takeaway' && (
          <div className="bill-row">
            <span>Delivery Charge</span>
            <span>₹{deliveryCharge.toFixed(2)}</span>
          </div>
        )}
        <div className="bill-row">
          <span>Taxes</span>
          <span>₹{taxes.toFixed(2)}</span>
        </div>
        <div className="bill-row grand-total">
          <span>Grand Total</span>
          <span>₹{grandTotal.toFixed(2)}</span>
        </div>
      </div>

      {/* Details Display */}
      <div className="user-details-display">
        <h3>Your details</h3>
        <p className="user-info">{name}, {phone}</p>
        
        {orderType === 'Dine In' && (
          <p className="user-location-info dining-info">
            Dining in for {members}
          </p>
        )}
        
        {orderType === 'Takeaway' && (
          <>
            <p className="user-location-info">
              <span style={{color: '#10B981'}}>📍</span> Delivery at Home - {address}
            </p>
            <p className="user-delivery-time">
              <span style={{color: '#10B981'}}>📞</span> Delivery in 42 mins
            </p>
          </>
        )}
      </div>
      
      {/* Swipe to Order Button - Uses ref AND the new guarded onClick handler */}
      <div 
        className="swipe-to-order" 
        ref={swipeRef}
        onClick={handleClick} // <-- Uses the new guarded handler
      >
        <div className="swipe-arrow">→</div>
        <span>Swipe to Order</span>
      </div>

      {/* Instructions Modal (Unchanged) */}
      {showInstructionsModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Add Cooking instructions</h3>
            <p>The restaurant will try its best to follow your request. However, refunds or cancellations in this regard won't be possible</p>
            <textarea 
              value={instructions}
              onChange={(e) => setInstructions(e.target.value)}
              rows="4"
              placeholder="Enter instructions..."
            />
            <div className="modal-actions">
              <button className="modal-btn-cancel" onClick={() => setShowInstructionsModal(false)}>Cancel</button>
              <button className="modal-btn-next" onClick={() => setShowInstructionsModal(false)}>Next</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}
